import re

def normalizar_pedido(texto: str) -> dict:
    match = re.match(r'PED-(\d+)\s*|\s*(item\s+)(\w+)\s*|\s*(qtd\s+)?(\d+)', texto, re.IGNORECASE)

    if not match:
        raise ValueError("Linha não contém o formato pedido")

    pedido, item, _, quantidade = match.groups()

    if quantidade is None:
        quantidade = 1

    return {
        "pedido": pedido,
        "item": item.upper(),
        "quantidade": int(quantidade)
    }

